
function luckyTopPrepare(r=S.run){const p=r?.lucky?.choice;if(p?.kind!=='top')return null;if(!p.topSlots){p.topSlots=Array(p.remaining+p.selected.length).fill(null);p.selected.forEach((id,i)=>p.topSlots[i]=id);p.selected=[];}if(!r.pendingChoice)r.pendingChoice={kind:'top',luckyTop:true,remaining:p.topSlots.filter(id=>id==null).length};return p;}
function luckyTopPlace(id,slot){const r=S.run,p=luckyTopPrepare(r);if(!p||busy||r.pendingChoice?.inspect||!Number.isInteger(slot)||slot<0||slot>=p.topSlots.length)return;const from=p.topSlots.indexOf(id),pool=p.topPool||r.hand,hand=pool.indexOf(id);if(from<0&&hand<0)return;if(from===slot)return;const previous=p.topSlots[slot];if(from>=0)p.topSlots[from]=previous;else{pool.splice(hand,1);if(previous!=null)pool.splice(hand,0,previous);}p.topSlots[slot]=id;p.remaining=p.topSlots.filter(x=>x==null).length;r.pendingChoice.remaining=p.remaining;p.topSelected=null;render();}
function luckyTopUndo(slot){const r=S.run,p=luckyTopPrepare(r);if(!p||busy||r.pendingChoice?.inspect||p.topSlots[slot]==null)return;(p.topPool||r.hand).push(p.topSlots[slot]);p.topSlots[slot]=null;p.remaining=p.topSlots.filter(x=>x==null).length;r.pendingChoice.remaining=p.remaining;render();}
function luckyTopHTML(r){const p=luckyTopPrepare(r);if(!p)return '';return '<section class="lucky-top-panel"><h3>山札に戻す順番</h3><p>手札を枠へ移動してください。1番から順に引きます。</p><div class="lucky-top-slots">'+p.topSlots.map((id,i)=>'<div class="lucky-top-slot" data-top-slot="'+i+'"><b>'+(i+1)+'</b>'+(id==null?'<span>ここに配置</span>':card(id)+'<button class="top-undo" data-top-undo="'+i+'">手札へ戻す</button>')+'</div>').join('')+'</div>'+(p.topPool?'<div class="lucky-top-pool cards">'+p.topPool.map(id=>'<div data-top-pool="'+id+'">'+card(id)+'</div>').join('')+'</div>':'')+'<button class="primary" onclick="luckyFinishChoice()" '+(p.remaining?'disabled':'')+'>確定</button></section>';}
const luckyTopBattleBase=battle;battle=function(){const r=S.run,p=luckyTopPrepare(r);let html=luckyTopBattleBase();if(!p)return html;html=html.replace(/<div class="hand-prompt" role="status">[\s\S]*?<\/div>/,'');return html+luckyTopHTML(r);};
let luckyTopSuppressClick=false;
function luckyTopCancel(){if(drag?.topOrder)clearDrag();}
function luckyTopDown(e,id){if(e.button!==0||S.run?.pendingChoice?.inspect||busy)return;e.preventDefault();e.stopImmediatePropagation();drag={type:'field',topOrder:true,id,pointerId:e.pointerId,startX:e.clientX,startY:e.clientY};makeGhost(e.currentTarget,e);e.currentTarget.classList.add('drag-source');}
document.addEventListener('pointerup',e=>{const d=drag;if(!d?.topOrder||d.pointerId!==e.pointerId)return;e.preventDefault();e.stopImmediatePropagation();const hit=document.elementFromPoint(e.clientX,e.clientY),slot=hit?.closest('[data-top-slot]');clearDrag();luckyTopSuppressClick=true;setTimeout(()=>luckyTopSuppressClick=false,0);if(slot)luckyTopPlace(d.id,+slot.dataset.topSlot);else if(Math.hypot(e.clientX-d.startX,e.clientY-d.startY)<8){const p=luckyTopPrepare();if(p){p.topSelected=d.id;render();}}},true);
const luckyTopRenderBase=render;render=function(){luckyTopPrepare();luckyTopRenderBase();const p=S.run?.lucky?.choice;if(page!=='battle'||p?.kind!=='top'){luckyTopCancel();return;}document.querySelectorAll('.hand .card').forEach((el,i)=>{const id=S.run.hand[i];el.onclick=()=>{if(!luckyTopSuppressClick){p.topSelected=id;render();}};el.classList.toggle('top-selected',p.topSelected===id);el.addEventListener('pointerdown',e=>luckyTopDown(e,id),true);});document.querySelectorAll('[data-top-slot]').forEach(el=>{const slot=+el.dataset.topSlot;el.onclick=()=>{if(!luckyTopSuppressClick&&p.topSelected!=null)luckyTopPlace(p.topSelected,slot);};const cardEl=el.querySelector('.card');if(cardEl)cardEl.addEventListener('pointerdown',e=>luckyTopDown(e,p.topSlots[slot]),true);});document.querySelectorAll('[data-top-pool] .card').forEach(el=>{const id=+el.closest('[data-top-pool]').dataset.topPool;el.addEventListener('pointerdown',e=>luckyTopDown(e,id),true);el.onclick=()=>{p.topSelected=id;render();};});document.querySelectorAll('[data-top-undo]').forEach(el=>el.onclick=e=>{e.stopPropagation();luckyTopUndo(+el.dataset.topUndo);});};
if(!globalThis.ASHBOUND_HEADLESS)render();
